import java.lang.reflect.*;
import java.util.*;

public class Inspect {
    static class Account {
        private final String id;
        private long balance;
        public Account(String id, long balance) { this.id = id; this.balance = balance; }
        public long balance() { return balance; }
        public void deposit(long amount) { balance += amount; }
        private void audit(String msg) { System.out.println("audit: " + msg); }
        @Override public String toString() { return id + ":" + balance; }
    }

    public static void main(String[] args) throws Exception {
        Class<?> c = Account.class;
        System.out.println("name      = " + c.getName());
        System.out.println("simple    = " + c.getSimpleName());
        System.out.println("modifiers = " + Modifier.toString(c.getModifiers()));
        System.out.println("super     = " + c.getSuperclass().getName());

        System.out.println("-- fields");
        for (Field f : c.getDeclaredFields())
            System.out.println(Modifier.toString(f.getModifiers()) + " "
                    + f.getType().getSimpleName() + " " + f.getName());
        System.out.println("-- methods");
        Arrays.stream(c.getDeclaredMethods()).map(Method::getName).sorted()
              .forEach(n -> System.out.println(n));

        Constructor<?> k = c.getDeclaredConstructor(String.class, long.class);
        Object acc = k.newInstance("A-1", 100L);
        Method dep = c.getMethod("deposit", long.class);
        dep.invoke(acc, 50L);
        System.out.println(acc);

        Method audit = c.getDeclaredMethod("audit", String.class);
        audit.setAccessible(true);
        audit.invoke(acc, "hello");

        Field id = c.getDeclaredField("id");
        id.setAccessible(true);
        id.set(acc, "HACKED");
        System.out.println(acc);

        try {
            c.getMethod("nope");
        } catch (NoSuchMethodException e) {
            System.out.println("NoSuchMethodException: " + e.getMessage());
        }
        try {
            Method m = c.getMethod("deposit", long.class);
            m.invoke(acc, "text");
        } catch (IllegalArgumentException e) {
            System.out.println("IllegalArgumentException: " + e.getMessage());
        }
        Method boom = Inspect.class.getDeclaredMethod("boom");
        try { boom.invoke(null); } catch (InvocationTargetException e) {
            System.out.println("wrapped: " + e + " cause=" + e.getCause());
        }
    }
    static void boom() { throw new IllegalStateException("inside"); }
}

