import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class MiniValidator {
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.FIELD)
    @interface NotBlank { String message() default "must not be blank"; }

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.FIELD)
    @interface Range { int min() default 0; int max() default Integer.MAX_VALUE; }

    @Retention(RetentionPolicy.SOURCE)
    @interface OnlyInSource {}

    static class Student {
        @NotBlank String name;
        @Range(min = 16, max = 100) int age;
        @OnlyInSource String note = "x";
        Student(String name, int age) { this.name = name; this.age = age; }
    }

    static List<String> validate(Object o) throws IllegalAccessException {
        List<String> errors = new ArrayList<>();
        for (Field f : o.getClass().getDeclaredFields()) {
            f.setAccessible(true);
            Object v = f.get(o);
            NotBlank nb = f.getAnnotation(NotBlank.class);
            if (nb != null && (v == null || v.toString().isBlank()))
                errors.add(f.getName() + ": " + nb.message());
            Range r = f.getAnnotation(Range.class);
            if (r != null) {
                int n = (Integer) v;
                if (n < r.min() || n > r.max())
                    errors.add(f.getName() + ": " + n + " not in ["
                            + r.min() + ", " + r.max() + "]");
            }
            System.out.println(f.getName() + " annotations = "
                    + Arrays.toString(f.getAnnotations()));
        }
        return errors;
    }
    public static void main(String[] args) throws Exception {
        System.out.println(validate(new Student("Asha", 20)));
        System.out.println(validate(new Student(" ", 12)));
    }
}

import java.lang.reflect.*;
import java.util.*;

public class Proxies {
    interface AccountService {
        long balance(String id);
        void deposit(String id, long amount);
    }
    static class RealService implements AccountService {
        private final Map<String, Long> data = new HashMap<>(Map.of("A-1", 100L));
        public long balance(String id) { return data.get(id); }
        public void deposit(String id, long amount) {
            if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
            data.merge(id, amount, Long::sum);
        }
    }
    static class TimingHandler implements InvocationHandler {
        private final Object target;
        TimingHandler(Object target) { this.target = target; }
        @Override
        public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            System.out.println("-> " + method.getName() + Arrays.toString(args));
            try {
                Object result = method.invoke(target, args);
                System.out.println("<- " + method.getName() + " = " + result);
                return result;
            } catch (InvocationTargetException e) {
                System.out.println("!! " + method.getName() + " threw " + e.getCause());
                throw e.getCause();
            }
        }
    }
    @SuppressWarnings("unchecked")
    static <T> T logged(T target, Class<T> iface) {
        return (T) Proxy.newProxyInstance(iface.getClassLoader(),
                new Class<?>[]{iface}, new TimingHandler(target));
    }
    public static void main(String[] args) {
        AccountService svc = logged(new RealService(), AccountService.class);
        svc.deposit("A-1", 25);
        System.out.println(svc.balance("A-1"));
        try { svc.deposit("A-1", -5); }
        catch (IllegalArgumentException e) { System.out.println("caught " + e.getMessage()); }
        System.out.println(svc.getClass().getName()
                + " isProxy=" + Proxy.isProxyClass(svc.getClass()));
        System.out.println(svc.getClass().getSuperclass().getName());
        System.out.println(svc.getClass().getInterfaces()[0].getSimpleName());
    }
}

import java.lang.invoke.*;

public class Handles {
    static class Box {
        volatile int count;
        String name = "box";
        String hello(String who) { return name + " greets " + who; }
    }
    public static void main(String[] args) throws Throwable {
        MethodHandles.Lookup lookup = MethodHandles.lookup();
        MethodHandle concat = lookup.findVirtual(String.class, "concat",
                MethodType.methodType(String.class, String.class));
        String s = (String) concat.invokeExact("Java", "Handle");
        System.out.println(s);
        MethodHandle hello = lookup.findVirtual(Box.class, "hello",
                MethodType.methodType(String.class, String.class));
        System.out.println((String) hello.invokeExact(new Box(), "Asha"));
        MethodHandle bound = hello.bindTo(new Box());
        System.out.println((String) bound.invokeExact("Ravi"));
        MethodHandle max = lookup.findStatic(Math.class, "max",
                MethodType.methodType(int.class, int.class, int.class));
        MethodHandle max10 = MethodHandles.insertArguments(max, 0, 10);
        System.out.println((int) max10.invokeExact(3) + " " + (int) max10.invokeExact(42));
        System.out.println(hello.type());
        try { Object o = concat.invokeExact((Object) "a", (Object) "b"); }
        catch (WrongMethodTypeException e) {
            System.out.println("WrongMethodTypeException: " + e.getMessage());
        }

        VarHandle COUNT = MethodHandles.lookup().findVarHandle(Box.class, "count", int.class);
        Box b = new Box();
        COUNT.set(b, 5);
        boolean ok = COUNT.compareAndSet(b, 5, 6);
        boolean bad = COUNT.compareAndSet(b, 5, 7);
        int prev = (int) COUNT.getAndAdd(b, 10);
        System.out.println(ok + " " + bad + " prev=" + prev + " now=" + (int) COUNT.getVolatile(b));
        VarHandle ARR = MethodHandles.arrayElementVarHandle(long[].class);
        long[] arr = new long[3];
        ARR.setRelease(arr, 1, 99L);
        System.out.println((long) ARR.getAcquire(arr, 1));
    }
}

