import java.io.IOException;
import java.lang.ref.WeakReference;
import java.nio.file.*;

public class LoaderDemo {
    /** Child-first loader: tries one directory before asking its parent. */
    static class DirLoader extends ClassLoader {
        private final Path dir;
        DirLoader(Path dir, ClassLoader parent) {
            super("dir-loader", parent);
            this.dir = dir;
        }

        @Override
        protected Class<?> loadClass(String name, boolean resolve)
                throws ClassNotFoundException {
            synchronized (getClassLoadingLock(name)) {
                if (name.startsWith("java.")) return super.loadClass(name, resolve);
                Class<?> c = findLoadedClass(name);
                if (c == null) {
                    try { c = findClass(name); }
                    catch (ClassNotFoundException e) { return super.loadClass(name, resolve); }
                }
                if (resolve) resolveClass(c);
                return c;
            }
        }

        @Override
        protected Class<?> findClass(String name) throws ClassNotFoundException {
            Path file = dir.resolve(name.replace('.', '/') + ".class");
            try {
                byte[] bytes = Files.readAllBytes(file);
                return defineClass(name, bytes, 0, bytes.length);
            } catch (IOException e) {
                throw new ClassNotFoundException(name);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("-- loader chain of this class");
        for (ClassLoader l = LoaderDemo.class.getClassLoader(); l != null; l = l.getParent())
            System.out.println(l.getName() + " : " + l.getClass().getName());
        System.out.println("String loader = " + String.class.getClassLoader());

        Path dir = Path.of("plugins");
        DirLoader loader = new DirLoader(dir, LoaderDemo.class.getClassLoader());
        Class<?> c1 = loader.loadClass("Plugin");
        Object p = c1.getDeclaredConstructor().newInstance();
        System.out.println(c1.getMethod("hello").invoke(p));
        Class<?> c2 = new DirLoader(dir, null).loadClass("Plugin");
        System.out.println("same name, same Class? " + (c1 == c2));
        System.out.println(c1.getClassLoader().getName());

        try {
            Plugin direct = (Plugin) p;
        } catch (ClassCastException e) {
            System.out.println("ClassCastException: " + e.getMessage().substring(0, 70) + "...");
        }

        WeakReference<ClassLoader> ref = new WeakReference<>(loader);
        loader = null; c1 = null; p = null;
        for (int i = 0; i < 5 && ref.get() != null; i++) { System.gc(); Thread.sleep(100); }
        System.out.println("loader collected? " + (ref.get() == null));
    }
}

