import java.lang.foreign.*;
import java.lang.invoke.MethodHandle;

public class NativeDemo {
    public static void main(String[] args) throws Throwable {
        Linker linker = Linker.nativeLinker();
        SymbolLookup stdlib = linker.defaultLookup();

        MethodHandle strlen = linker.downcallHandle(
                stdlib.find("strlen").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.JAVA_LONG, ValueLayout.ADDRESS));
        MethodHandle getpid = linker.downcallHandle(
                stdlib.find("getpid").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.JAVA_INT));

        try (Arena arena = Arena.ofConfined()) {
            MemorySegment cString = arena.allocateUtf8String("Hello, native world");
            long len = (long) strlen.invokeExact(cString);
            System.out.println("strlen = " + len);

            MemorySegment ints = arena.allocateArray(ValueLayout.JAVA_INT, 5);
            for (int i = 0; i < 5; i++) ints.setAtIndex(ValueLayout.JAVA_INT, i, i * i);
            int sum = 0;
            for (int i = 0; i < 5; i++) sum += ints.getAtIndex(ValueLayout.JAVA_INT, i);
            System.out.println("sum of squares = " + sum + ", segment bytes = " + ints.byteSize());
        }
        int pid = (int) getpid.invokeExact();
        System.out.println("same pid as ProcessHandle? " + (pid == ProcessHandle.current().pid()));

        MemorySegment leaked;
        try (Arena a = Arena.ofConfined()) { leaked = a.allocate(8); }
        try { leaked.get(ValueLayout.JAVA_BYTE, 0); }
        catch (IllegalStateException e) { System.out.println("after close: " + e.getMessage()); }
    }
}

import java.util.ArrayList;
import java.util.List;

public class Victim {
    static final Object LOCK_A = new Object();
    static final Object LOCK_B = new Object();
    static final List<byte[]> retained = new ArrayList<>();

    static void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) { return; }
    }

    public static void main(String[] args) {
        Thread spin = new Thread(() -> {
            long x = 0;
            while (true) { x += Math.sqrt(x + 1); if (x < 0) x = 0; }
        }, "cpu-spinner");
        spin.setDaemon(true);
        spin.start();

        Thread t1 = new Thread(() -> {
            synchronized (LOCK_A) { sleep(300); synchronized (LOCK_B) { } }
        }, "worker-1");
        Thread t2 = new Thread(() -> {
            synchronized (LOCK_B) { sleep(300); synchronized (LOCK_A) { } }
        }, "worker-2");
        t1.setDaemon(true); t2.setDaemon(true);
        t1.start(); t2.start();

        Thread leaker = new Thread(() -> {
            while (true) {
                retained.add(new byte[100_000]);
                sleep(20);
                if (retained.size() > 300) retained.clear();
            }
        }, "leaker");
        leaker.setDaemon(true);
        leaker.start();

        System.out.println("Victim running, pid " + ProcessHandle.current().pid());
        sleep(120_000);
    }
}

import java.lang.management.ManagementFactory;
import java.lang.management.ThreadInfo;
import java.lang.management.ThreadMXBean;

public class Watchdog {
    static final Object A = new Object();
    static final Object B = new Object();

    static void pause() {
        try { Thread.sleep(200); } catch (InterruptedException e) { return; }
    }

    public static void main(String[] args) throws Exception {
        Thread t1 = new Thread(() -> {
            synchronized (A) { pause(); synchronized (B) { } }
        }, "worker-1");
        Thread t2 = new Thread(() -> {
            synchronized (B) { pause(); synchronized (A) { } }
        }, "worker-2");
        t1.setDaemon(true); t2.setDaemon(true);
        t1.start(); t2.start();
        Thread.sleep(600);
        ThreadMXBean mx = ManagementFactory.getThreadMXBean();
        long[] ids = mx.findDeadlockedThreads();
        System.out.println("deadlocked threads: " + (ids == null ? 0 : ids.length));
        for (ThreadInfo info : mx.getThreadInfo(ids)) {
            System.out.println(info.getThreadName() + " is " + info.getThreadState()
                + " waiting for " + info.getLockName() + " held by " + info.getLockOwnerName());
        }
        System.out.println("live threads: " + mx.getThreadCount());
    }
}
